WITH src AS (
 SELECT x.*,md5('fbmn:tv-wave2:'||x.source_key) AS dg
 FROM jsonb_to_recordset('[{"district":"Huyện Tiểu Cần","name":"Nhà sách Minh Tú","address_line":"22 Hai Bà Trưng, Khóm 1, thị trấn Tiểu Cần cũ","category":"nha_sach","phone":"02943822258","tax_code":null,"source_key":"web:tv-tc-minh-tu-22-hbt","source_url":"https://sotayvang.com/nha-sach-minh-tu-khom-1/","verification_note":"Nguồn danh bạ, chưa xác minh ghé."},{"district":"Huyện Tiểu Cần","name":"Nhà sách Ngọc Bá 2","address_line":"Khu vực Tiểu Cần cũ (Google Maps chưa công bố số nhà)","category":"nha_sach","phone":"0919598765","tax_code":null,"source_key":"gmap:ChIJFaQ2KKk_oDERqtbae9kuUow","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Ng%E1%BB%8Dc%20B%C3%A1%202%20Ti%E1%BB%83u%20C%E1%BA%A7n%20Tr%C3%A0%20Vinh&query_place_id=ChIJFaQ2KKk_oDERqtbae9kuUow","verification_note":"Chưa có số nhà; cần xác minh bán sách và vị trí."},{"district":"Huyện Tiểu Cần","name":"Văn phòng phẩm Nguyễn Sang","address_line":"202 Võ Thị Sáu, Khóm 1, thị trấn Tiểu Cần cũ","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"gmap:ChIJI6K_VQk_oDERnCjYR9V079g","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Nguy%E1%BB%85n%20Sang%20Ti%E1%BB%83u%20C%E1%BA%A7n%20Tr%C3%A0%20Vinh&query_place_id=ChIJI6K_VQk_oDERnCjYR9V079g","verification_note":"Có hồ sơ Tin học Nguyễn Sang cùng khu vực; chưa xác minh là cùng pháp nhân; không gán MST khi chưa khớp."},{"district":"Huyện Tiểu Cần","name":"Văn phòng phẩm Thầy Khoa","address_line":"Khu vực Tiểu Cần cũ (Plus Code V54M+P4W)","category":"van_phong_pham","phone":"0942131970","tax_code":null,"source_key":"gmap:ChIJy8-NDd4_oDERwg-U90zdXKE","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Th%E1%BA%A7y%20Khoa%20Ti%E1%BB%83u%20C%E1%BA%A7n%20Tr%C3%A0%20Vinh&query_place_id=ChIJy8-NDd4_oDERwg-U90zdXKE","verification_note":"Chưa có số nhà, cần xác minh mặt hàng VPP."},{"district":"Huyện Tiểu Cần","name":"Văn phòng phẩm Thầy Tâm","address_line":"Khu vực Tiểu Cần cũ (Plus Code V54M+VJ9)","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"gmap:ChIJCV9sBAA_oDERq-O-lULDQ4w","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Th%E1%BA%A7y%20T%C3%A2m%20Ti%E1%BB%83u%20C%E1%BA%A7n%20Tr%C3%A0%20Vinh&query_place_id=ChIJCV9sBAA_oDERq-O-lULDQ4w","verification_note":"Chưa có số nhà; cần đối chiếu thực địa."},{"district":"Huyện Tiểu Cần","name":"Hộ kinh doanh Nhà sách Phát Đạt","address_line":"Khóm 3, thị trấn Cầu Quan cũ, huyện Tiểu Cần","category":"nha_sach","phone":null,"tax_code":"8342797495001","source_key":"web:tv-tc-phat-dat-8342797495001","source_url":"https://tracuumst.com/8342797495-001-ho-kinh-doanh-nha-sach-phat-dat","verification_note":"Hồ sơ thuế ghi địa chỉ cũ và hoạt động tại thời điểm tra cứu; chưa chứng minh quầy thực tế vẫn mở."},{"district":"Huyện Châu Thành","name":"Văn phòng phẩm Minh Phương","address_line":"25 Khóm 2, thị trấn Châu Thành cũ, huyện Châu Thành, Trà Vinh","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"web:tv-ct-minh-phuong-25","source_url":"https://vn-vi438578-cu-a-ha-ng-va-n-pho-ng-pha-m-minh-phu-o-ng.contact.page/","verification_note":"Số điện thoại nguồn bị che; tránh nhầm huyện Châu Thành tỉnh Bến Tre cũ."},{"district":"Huyện Châu Thành","name":"Văn phòng phẩm - Photocopy Pha Ly","address_line":"01 ĐT911, ấp Ô Bắp, huyện Châu Thành cũ, Trà Vinh","category":"van_phong_pham","phone":"0342329110","tax_code":null,"source_key":"web:tv-ct-pha-ly-1-dt911","source_url":"https://www.viet-biz.com/en/v%C4%83n-ph%C3%B2ng-ph%E1%BA%A9m-photocopy-pha-ly-0342-329-110","verification_note":"Địa chỉ theo danh bạ cũ, GPS chưa xác minh."},{"district":"Huyện Châu Thành","name":"Hiệu sách Trung Tâm","address_line":"354 Khóm 2, thị trấn Châu Thành cũ, huyện Châu Thành, Trà Vinh","category":"nha_sach","phone":"0986864158","tax_code":null,"source_key":"gmap:ChIJO6_m3B0YoDERWQ0oR22qNxs","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20S%C3%A1ch%20Trung%20T%C3%A2m%20Ch%C3%A2u%20Th%C3%A0nh%20Tr%C3%A0%20Vinh%20Tr%C3%A0%20Vinh&query_place_id=ChIJO6_m3B0YoDERWQ0oR22qNxs","verification_note":"Cần kiểm tra tên biển hiệu và số nhà."},{"district":"Huyện Châu Thành","name":"Cửa hàng Ngọc Hân","address_line":"Khóm 2, thị trấn Châu Thành cũ, huyện Châu Thành, Trà Vinh","category":"van_phong_pham","phone":null,"tax_code":"2100152923","source_key":"web:tv-ct-ngoc-han-2100152923","source_url":"https://dauthau.asia/businesslistings/detail/CUA-HANG-NGOC-HAN-101451/","verification_note":"Nguồn nhà cung cấp hàng VPP; chưa rõ có quầy bán lẻ. Không nhầm cửa hàng tên Ngọc Hân tại TP Trà Vinh."},{"district":"Huyện Châu Thành","name":"Văn phòng phẩm - Tin học Thành Khoa","address_line":"Ấp Hòa Lạc C, xã Lương Hòa A cũ, huyện Châu Thành, Trà Vinh","category":"van_phong_pham","phone":null,"tax_code":"2100634067","source_key":"web:tv-ct-thanh-khoa-2100634067","source_url":"https://dauthau.net/vi/dn/DOANH-NGHIEP-TN-VAN-PHONG-PHAM-TIN-HOC-THANH-KHOA/","verification_note":"Nguồn doanh nghiệp; chưa xác minh quầy bán lẻ và tình trạng hoạt động."},{"district":"Huyện Cầu Ngang","name":"2a Bookstore - chi nhánh Mỹ Long","address_line":"Số 11, Khóm 1, thị trấn Mỹ Long cũ, huyện Cầu Ngang","category":"nha_sach","phone":"02942214460","tax_code":null,"source_key":"web:tv-cn-2a-bookstore-my-long","source_url":"https://www.viet-biz.com/a-bookstore-0294-2214-460","verification_note":"Danh bạ gắn thành phố Trà Vinh nhưng địa chỉ chi nhánh cụ thể ghi thị trấn Mỹ Long, Cầu Ngang."},{"district":"Huyện Cầu Ngang","name":"Văn phòng phẩm Bảy Hồng","address_line":"260 đường 3 Tháng 2, Khóm Minh Thuận A, thị trấn Cầu Ngang cũ","category":"van_phong_pham","phone":null,"tax_code":"2100154102","source_key":"web:tv-cn-bay-hong-2100154102","source_url":"https://dauthau.asia/businesslistings/detail/Cua-hang-van-phong-pham-va-thiet-bi-tin-hoc-Bay-Hong-102875/","verification_note":"Có danh bạ đánh dấu đóng cửa, phải xác minh thực tế, không khẳng định đang hoạt động."},{"district":"Huyện Cầu Ngang","name":"Văn phòng phẩm Hà Vy","address_line":"237 đường 3 Tháng 2, thị trấn Cầu Ngang cũ","category":"van_phong_pham","phone":"02943825381","tax_code":null,"source_key":"web:tv-cn-ha-vy-237-3thang2","source_url":"https://sotayvang.com/cua-hang-van-phong-pham-ha-vy-tt-cau-ngang/","verification_note":"Danh bạ cũ, số điện thoại chưa xác minh thực tế."},{"district":"Huyện Cầu Ngang","name":"Sách Cầu Ngang","address_line":"262 đường 3 Tháng 2, Khóm Minh Thuận A, thị trấn Cầu Ngang cũ","category":"nha_sach","phone":null,"tax_code":null,"source_key":"gmap:ChIJgfqPijEhoDERz9uuAIEZbZQ","source_url":"https://www.google.com/maps/search/?api=1&query=S%C3%A1ch%20C%E1%BA%A7u%20Ngang%20Tr%C3%A0%20Vinh&query_place_id=ChIJgfqPijEhoDERz9uuAIEZbZQ","verification_note":"Gần điểm Bảy Hồng số 260; cần xác minh là cửa hàng riêng hay hai tên cùng địa điểm."},{"district":"Huyện Cầu Ngang","name":"Phương Nguyên - Tin học và Văn phòng phẩm","address_line":"94, Khóm Minh Thuận, thị trấn Cầu Ngang cũ","category":"van_phong_pham","phone":"02943825190","tax_code":null,"source_key":"gmap:ChIJvU3Xc3AhoDERPeNI-nqOvkM","source_url":"https://www.google.com/maps/search/?api=1&query=Ph%C6%B0%C6%A1ng%20Nguy%C3%AAn%20Computer%20Stationery%20Store%20C%E1%BA%A7u%20Ngang%20Tr%C3%A0%20Vinh&query_place_id=ChIJvU3Xc3AhoDERPeNI-nqOvkM","verification_note":"Kiểm tra danh mục VPP và biển hiệu thực tế."},{"district":"Huyện Cầu Ngang","name":"Công ty TNHH TM Kadas Paper","address_line":"Ấp Lạc Thạnh B, xã Thạnh Hòa Sơn cũ, huyện Cầu Ngang","category":"van_phong_pham","phone":null,"tax_code":"2100610193","source_key":"web:tv-cn-kadas-paper-2100610193","source_url":"https://thongtindoanhnghiep.co/2100610193-cong-ty-tnhh-thuong-mai-kadas-paper","verification_note":"Nguồn doanh nghiệp ngành giấy/VPP; nguồn có thể cũ, chưa chứng minh cửa hàng bán lẻ."}]'::jsonb) AS x(
   district text,name text,address_line text,category text,phone text,tax_code text,
   source_key text,source_url text,verification_note text)
), ins AS (
 INSERT INTO public.field_prospects(
  id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,
  note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT
  (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
  NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
  s.name,s.address_line,'Trà Vinh',s.district,s.category,s.phone,s.tax_code,
  'Nguồn nghiên cứu công khai 21/11/2026; Chưa ghé; GPS chưa xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
  'new','manual',s.source_key,s.source_url,'2026-11-21-tra-vinh-old-wave-02-three-districts'
 FROM src s
 WHERE s.district IN ('Huyện Tiểu Cần','Huyện Châu Thành','Huyện Cầu Ngang')
  AND s.source_url LIKE 'https://%'
  AND NOT EXISTS (
   SELECT 1 FROM public.customers c WHERE c.province='Trà Vinh' AND c.district=s.district
    AND lower(btrim(c.name))=lower(btrim(s.name)))
  AND NOT EXISTS (
   SELECT 1 FROM public.field_prospects p WHERE p.province='Trà Vinh' AND p.district=s.district
    AND (p.research_source_key=s.source_key OR
      (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))))
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,phone,tax_code
)
SELECT district, count(*)::int AS inserted, count(*) FILTER (WHERE phone IS NOT NULL)::int phones,
 count(*) FILTER (WHERE tax_code IS NOT NULL)::int tax_codes FROM ins GROUP BY district ORDER BY district;
